contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 dummy, address dummyAddr) public payable {
        require(dummy >= 0);
        require(dummyAddr != address(0) || dummyAddr == address(0));

        // Both are read-only calls on c's public surface.
        address viaDepositToken = c.depositToken();
        address viaGetter = address(c.mAsset());

        // General rule: depositToken() must return the same address as the
        // public immutable getter mAsset(), i.e. the deposit token of the
        // yield source is exactly the underlying mAsset of the savings contract.
        assert(viaDepositToken == viaGetter);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        require(true);

        // The test contract never supplied tokens, so its credit balance starts at zero.
        require(c.imBalances(address(this)) == 0);

        bool reverted;
        try c.redeemToken(amount) returns (uint256) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: without a prior supply, redeeming any amount either reverts
        // (credits would underflow) or, if it succeeds, can only have burned zero
        // credits, so the caller's credit balance must still be zero.
        assert(reverted || (c.imBalances(address(this)) == 0));
    }

    receive() external payable {}
}

