contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, address to, bool doRevert) public payable {
        require(to != address(0));
        require(amount > 0);

        uint256 beforeCredits = c.imBalances(to);

        bool reverted;
        if (doRevert) {
            // force a revert path via a fresh call that will fail on transferFrom
            try c.supplyTokenTo(amount, to) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.supplyTokenTo(amount, to) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterCredits = c.imBalances(to);

        assert(
            (!reverted && afterCredits > beforeCredits) ||
            (reverted && afterCredits == beforeCredits)
        );
    }

    receive() external payable {}
}

