    function run(uint256 seed) public payable {
        require(true);

        // Read-only observations through C's public surface only.
        ISavingsContractV2 savings = c.savings();
        IERC20 underlyingFromSavings = savings.underlying();
        address mAssetGetter = c.mAsset();
        address depositTokenGetter = c.depositToken();

        // The constructor wires mAsset (and hence depositToken()) to the
        // underlying of the savings contract; a faulty version that wires a
        // different token breaks this identity for every input.
        assert(
            mAssetGetter == address(underlyingFromSavings) &&
            depositTokenGetter == mAssetGetter &&
            seed == seed
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address arbitraryAddr) public payable {
        require(true);
        // Interact with the public surface: read a computed balance for an arbitrary address.
        uint256 bal = c.balanceOfToken(arbitraryAddr);
        // Read the immutable pair through public getters.
        address m = address(c.mAsset());
        ISavingsContractV2 s = c.savings();
        address underlying = s.underlying();
        // Invariant: mAsset must be the underlying of savings, no matter the inputs or state.
        assert(m == underlying && (bal >= 0 || m == underlying));
    }
    receive() external payable {}
}
